BEGIN;
CREATE TABLE IF NOT EXISTS accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),code text NOT NULL,name text NOT NULL,type text NOT NULL CHECK(type IN ('asset','liability','equity','revenue','expense')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),postable boolean NOT NULL DEFAULT true,UNIQUE(organization_id,code));
CREATE TABLE IF NOT EXISTS journals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),period_id uuid NOT NULL REFERENCES fiscal_periods(id),reference text,description text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','posted','reversed')),preparer_id uuid NOT NULL REFERENCES users(id),approver_id uuid REFERENCES users(id),posted_at timestamptz,reversed_from_id uuid REFERENCES journals(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(approver_id IS NULL OR approver_id<>preparer_id));
CREATE TABLE IF NOT EXISTS journal_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),journal_id uuid NOT NULL REFERENCES journals(id) ON DELETE RESTRICT,account_id uuid NOT NULL REFERENCES accounts(id),line_no integer NOT NULL CHECK(line_no>0),debit_minor bigint NOT NULL DEFAULT 0 CHECK(debit_minor>=0),credit_minor bigint NOT NULL DEFAULT 0 CHECK(credit_minor>=0),memo text NOT NULL DEFAULT '',CHECK((debit_minor>0 AND credit_minor=0) OR (credit_minor>0 AND debit_minor=0)),UNIQUE(journal_id,line_no));
CREATE TABLE IF NOT EXISTS command_idempotency (organization_id uuid NOT NULL REFERENCES organizations(id),command_type text NOT NULL,idempotency_key text NOT NULL,payload_hash text NOT NULL,result_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,command_type,idempotency_key));
CREATE TABLE IF NOT EXISTS posting_events (id bigserial PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),journal_id uuid NOT NULL UNIQUE REFERENCES journals(id),sequence_no bigint NOT NULL,previous_hash text NOT NULL,posting_hash text NOT NULL UNIQUE,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,sequence_no));
CREATE TABLE IF NOT EXISTS business_audit_events (id bigserial PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),actor_id uuid REFERENCES users(id),event_type text NOT NULL,entity_type text NOT NULL,entity_id uuid,request_id text,correlation_id text,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION protect_posted_journal() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status IN ('posted','reversed') THEN RAISE EXCEPTION 'POSTED_JOURNAL_IMMUTABLE' USING ERRCODE='P0001';END IF;RETURN COALESCE(NEW,OLD);END $$;
DROP TRIGGER IF EXISTS trg_protect_posted_journal ON journals;CREATE TRIGGER trg_protect_posted_journal BEFORE UPDATE OR DELETE ON journals FOR EACH ROW EXECUTE FUNCTION protect_posted_journal();
CREATE OR REPLACE FUNCTION protect_posted_journal_lines() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE s text;BEGIN SELECT status INTO s FROM journals WHERE id=COALESCE(OLD.journal_id,NEW.journal_id);IF s IN ('posted','reversed') THEN RAISE EXCEPTION 'POSTED_JOURNAL_IMMUTABLE' USING ERRCODE='P0001';END IF;RETURN COALESCE(NEW,OLD);END $$;
DROP TRIGGER IF EXISTS trg_protect_posted_lines ON journal_lines;CREATE TRIGGER trg_protect_posted_lines BEFORE UPDATE OR DELETE ON journal_lines FOR EACH ROW EXECUTE FUNCTION protect_posted_journal_lines();
COMMIT;
